(()=>{const e=document.querySelector("#theme-toggle"),r=e?.querySelector(".theme-toggle-label");if(!e||!r)return;const a="site-theme",s=localStorage.getItem(a),c=window.matchMedia("(prefers-color-scheme: dark)").matches;let t=s==="dark"||s!=="light"&&c;const l=()=>{document.documentElement.dataset.theme=t?"dark":"light";const o=t?"light":"dark";e.setAttribute("aria-pressed",String(t)),e.setAttribute("aria-label",`Switch to ${o} mode`),e.title=`Switch to ${o} mode`,r.textContent=`${o[0].toUpperCase()}${o.slice(1)} mode`};l(),e.addEventListener("click",()=>{t=!t,localStorage.setItem(a,t?"dark":"light"),l()})})();
